//! Dumps the plugin's `mesures` JSON Schema (P-00 §5, acceptance criterion 6).

use rgaa_analysis_colorvision::{AvisModele, Mesures, SimulationMesure};
use schemars::schema_for;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let document = serde_json::json!({
        "$comment": "Generated by `cargo run -p rgaa-analysis-colorvision --bin dump-colorvision-schemas`.",
        "colorvision": {
            "mesures": schema_for!(Mesures),
            "simulation": schema_for!(SimulationMesure),
            "avis_modele": schema_for!(AvisModele),
        }
    });
    println!("{}", serde_json::to_string_pretty(&document)?);
    Ok(())
}
